mapper.select:
SELECT segment_id, session_id, lower(segment) as startWatchTime, upper(segment) as endWatchTime, create_time, update_time
FROM video_play_segment
WHERE session_id = #{sessionId} AND segment_id = #{segmentId};

mapper.update:
UPDATE video_play_segment
SET segment = int4range(lower(segment), #{endWatchTimeInSeconds}), update_time = #{updateTime}
WHERE session_id = #{id.sessionId} AND segment_id = #{id.segmentId} AND NOT segment @> int4range(#{startWatchTimeInSeconds}, #{endWatchTimeInSeconds});
